const cfg = $json;

if (!cfg.locationId) throw new Error('Missing locationId');
if (!cfg.apiKey) throw new Error('Missing apiKey in Config node');

const baseUrl = (cfg.apiBaseUrl || 'https://services.leadconnectorhq.com').replace(/\/$/, '');
const locationId = cfg.locationId;
const dryRun = !!cfg.dryRun;

const headers = {
  Authorization: `Bearer ${cfg.apiKey}`,
  Version: '2021-07-28',
  'Content-Type': 'application/json',
  Accept: 'application/json',
};

async function doHttpRequest(options) {
  if (typeof $httpRequest === 'function') {
    return await $httpRequest(options);
  }
  if (typeof this !== 'undefined' && this?.helpers?.httpRequest) {
    return await this.helpers.httpRequest(options);
  }
  throw new Error('HTTP not available in Code node runtime. Use HTTP Request nodes for API calls.');
}

async function apiRequest(method, path, body) {
  const options = {
    method,
    url: `${baseUrl}${path}`,
    headers,
    json: true,
  };

  if (body !== undefined) {
    options.body = body;
  }

  try {
    const data = await doHttpRequest.call(this, options);
    return { ok: true, status: 200, data };
  } catch (err) {
    const status = err?.statusCode || err?.httpCode || err?.cause?.statusCode || 500;
    const data = err?.response?.body || err?.message || err;
    return { ok: false, status, data };
  }
}

function getArrayPayload(obj, preferredKeys = []) {
  if (Array.isArray(obj)) return obj;
  for (const key of preferredKeys) {
    if (Array.isArray(obj?.[key])) return obj[key];
  }
  if (Array.isArray(obj?.data)) return obj.data;
  if (Array.isArray(obj?.customFields)) return obj.customFields;
  if (Array.isArray(obj?.tags)) return obj.tags;
  if (Array.isArray(obj?.data?.customFields)) return obj.data.customFields;
  if (Array.isArray(obj?.data?.tags)) return obj.data.tags;
  return [];
}

function normalizeType(value) {
  const v = String(value || '').toUpperCase();
  if (!v) return '';
  if (['DROPDOWN', 'SINGLE_OPTIONS', 'SINGLE_SELECT', 'SELECT', 'OPTION'].some((x) => v.includes(x))) return 'DROPDOWN_SINGLE';
  if (['DATE_TIME', 'DATETIME', 'DATE'].some((x) => v.includes(x))) return 'DATETIME';
  return v;
}

function extractFieldType(field) {
  return normalizeType(field?.dataType || field?.fieldType || field?.type || field?.valueType);
}

function extractFieldName(field) {
  return field?.name || field?.label || field?.fieldName || '';
}

function extractTagName(tag) {
  if (typeof tag === 'string') return tag;
  return tag?.name || tag?.label || tag?.tag || '';
}

const requiredFields = [
  {
    name: 'Lead Temperature',
    requiredType: 'DROPDOWN_SINGLE',
    options: ['Cold', 'Warm', 'Hot', 'Client', 'Disqualified'],
  },
  {
    name: 'Warm Source',
    requiredType: 'DROPDOWN_SINGLE',
    options: ['LinkedIn Lead Form', 'LinkedIn DM', 'LinkedIn Post', 'Instagram', 'Facebook', 'Meta Lead Form', 'Meta Traffic', 'Meta Remarketing', 'Email Outbound', 'Email Inbound', 'SMS', 'Website', 'Referral'],
  },
  {
    name: 'Warm Trigger Type',
    requiredType: 'DROPDOWN_SINGLE',
    options: ['Form Submission', 'Direct Message Reply', 'Email Reply', 'Email Click', 'SMS Reply', 'Website Engagement', 'Multi-Visit Behavior', 'Referral'],
  },
  {
    name: 'Warm Date',
    requiredType: 'DATETIME',
  },
  {
    name: 'Primary Engagement Channel',
    requiredType: 'DROPDOWN_SINGLE',
    options: ['Social', 'Paid Ads', 'Email', 'SMS', 'Website', 'Referral'],
  },
];

const requiredTags = [
  'Warm  Instagram',
  'Warm  Facebook',
  'Warm  LinkedIn',
  'Warm  LinkedIn DM',
  'Warm  LinkedIn Lead Form',
  'Warm  Meta Lead Form',
  'Warm  Meta Traffic',
  'Warm  Meta Remarketing',
  'Warm  Email Outbound',
  'Warm  Email Inbound',
  'Warm  SMS',
  'Warm  Website',
  'Warm  Referral',
  'Lead Status: Warm',
  'Stage: MQL',
];

const fieldsRes = await apiRequest.call(this, 'GET', `/locations/${locationId}/customFields?model=contact`);
if (!fieldsRes.ok) {
  throw new Error(`Failed to fetch custom fields: ${fieldsRes.status} ${JSON.stringify(fieldsRes.data)}`);
}

const tagsRes = await apiRequest.call(this, 'GET', `/locations/${locationId}/tags`);
if (!tagsRes.ok) {
  throw new Error(`Failed to fetch tags: ${tagsRes.status} ${JSON.stringify(tagsRes.data)}`);
}

const existingFields = getArrayPayload(fieldsRes.data, ['customFields']);
const existingTags = getArrayPayload(tagsRes.data, ['tags']);

const fieldByName = new Map();
for (const field of existingFields) {
  const name = extractFieldName(field);
  if (name) fieldByName.set(name, field);
}

const tagNameSet = new Set(existingTags.map(extractTagName).filter(Boolean));

const conflicts = [];
const fieldReport = [];
const tagReport = [];
const fieldsToCreate = [];
const tagsToCreate = [];

for (const req of requiredFields) {
  const existing = fieldByName.get(req.name);
  if (existing) {
    const existingType = extractFieldType(existing);
    if (existingType !== req.requiredType) {
      conflicts.push({
        fieldName: req.name,
        existingType: existing?.dataType || existing?.fieldType || existing?.type || 'UNKNOWN',
        requiredType: req.requiredType,
      });
    } else {
      fieldReport.push({
        fieldName: req.name,
        fieldId: existing.id || existing._id || 'N/A',
        type: req.requiredType,
        action: 'Reused',
      });
    }
  } else {
    fieldsToCreate.push(req);
  }
}

if (conflicts.length > 0) {
  const lines = conflicts.map((c) => `${c.fieldName} | ${c.existingType} | ${c.requiredType}`);
  throw new Error(`CONFLICT:\n${lines.join('\n')}`);
}

for (const tag of requiredTags) {
  if (tagNameSet.has(tag)) {
    tagReport.push({ tagName: tag, action: 'Already Exists' });
  } else {
    tagsToCreate.push(tag);
  }
}

async function createField(req) {
  const candidateBodies = [];

  if (req.requiredType === 'DROPDOWN_SINGLE') {
    const optionObjects = (req.options || []).map((o) => ({ label: o, value: o }));
    for (const dataType of ['SINGLE_OPTIONS', 'DROPDOWN', 'SINGLE_SELECT']) {
      candidateBodies.push({ name: req.name, model: 'contact', dataType, picklistOptions: req.options || [] });
      candidateBodies.push({ name: req.name, model: 'contact', dataType, options: req.options || [] });
      candidateBodies.push({ name: req.name, model: 'contact', dataType, picklistOptions: optionObjects });
      candidateBodies.push({ name: req.name, objectKey: 'contact', dataType, options: optionObjects });
    }
  } else if (req.requiredType === 'DATETIME') {
    for (const dataType of ['DATE_TIME', 'DATETIME', 'DATE']) {
      candidateBodies.push({ name: req.name, model: 'contact', dataType });
      candidateBodies.push({ name: req.name, objectKey: 'contact', dataType });
    }
  }

  let lastError = null;
  for (const body of candidateBodies) {
    const res = await apiRequest.call(this, 'POST', `/locations/${locationId}/customFields`, body);
    if (res.ok) return res.data;
    lastError = { status: res.status, data: res.data, body };
  }

  throw new Error(`Failed creating field ${req.name}: ${JSON.stringify(lastError)}`);
}

async function createTag(name) {
  const candidateBodies = [
    { name },
    { tag: name },
    { tags: [name] },
    { tags: [{ name }] },
  ];

  let lastError = null;
  for (const body of candidateBodies) {
    const res = await apiRequest.call(this, 'POST', `/locations/${locationId}/tags`, body);
    if (res.ok) return res.data;
    lastError = { status: res.status, data: res.data, body };
  }

  throw new Error(`Failed creating tag ${name}: ${JSON.stringify(lastError)}`);
}

if (!dryRun) {
  for (const req of fieldsToCreate) {
    const created = await createField.call(this, req);
    fieldReport.push({
      fieldName: req.name,
      fieldId: created?.id || created?.data?.id || created?.customField?.id || 'N/A',
      type: req.requiredType,
      action: 'Created',
    });
  }

  for (const name of tagsToCreate) {
    await createTag.call(this, name);
    tagReport.push({ tagName: name, action: 'Created' });
  }
} else {
  for (const req of fieldsToCreate) {
    fieldReport.push({ fieldName: req.name, fieldId: 'N/A', type: req.requiredType, action: 'Planned Create (dryRun)' });
  }
  for (const name of tagsToCreate) {
    tagReport.push({ tagName: name, action: 'Planned Create (dryRun)' });
  }
}

fieldReport.sort((a, b) => a.fieldName.localeCompare(b.fieldName));
tagReport.sort((a, b) => a.tagName.localeCompare(b.tagName));

return [
  {
    json: {
      dryRun,
      locationId,
      CUSTOM_FIELDS: fieldReport,
      TAGS: tagReport,
    },
  },
];
